<?php require_once 'db.php';require_once 'functions.php';$u=login_required($pdo);if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if(($_POST['action']??'')==='read')$pdo->prepare('UPDATE notifications SET is_read=1,read_at=NOW() WHERE id=? AND user_id=?')->execute([(int)$_POST['id'],$u['id']]);if(($_POST['action']??'')==='all')$pdo->prepare('UPDATE notifications SET is_read=1,read_at=NOW() WHERE user_id=?')->execute([$u['id']]);}$s=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC');$s->execute([$u['id']]);$rows=$s->fetchAll();?><?php $pageTitle='Notifikasi'; include 'layout_top.php'; ?><div class="head"><div><h1>Notifications</h1></div><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf())?>"><input type="hidden" name="action" value="all"><button class="btn-sm secondary">Mark All Read</button></form></div><?php foreach($rows as $n):?><div class="card <?=!$n['is_read']?'unread':''?>"><b><?=e($n['title']?:$n['type'])?></b><p><?=e($n['message'])?></p><small><?=e($n['created_at'])?></small><?php if(!$n['is_read']):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf())?>"><input type="hidden" name="action" value="read"><input type="hidden" name="id" value="<?=$n['id']?>"><button class="btn-sm primary">Read</button></form><?php endif;?></div><?php endforeach;?><?php if(!$rows):?><div class="card">Belum ada notifikasi.</div><?php endif;?><?php include 'layout_bottom.php'; ?>
